function validateSkillCatalog(catalog = exports.SKILL_CATALOG) {
    const normalizedNames = new Map();
    const searchableLabels = new Map();
    for (const skill of catalog) {
        if (!skill.name.trim() || !skill.normalizedName.trim()) {
            throw new Error('Skill catalog contains an empty name or normalizedName.');
        }
        const normalizedKey = skill.normalizedName.trim().toLocaleLowerCase('vi');
        const previousNormalized = normalizedNames.get(normalizedKey);
        if (previousNormalized) {
            throw new Error(`Duplicate normalizedName "${skill.normalizedName}" for "${previousNormalized}" and "${skill.name}".`);
        }
        normalizedNames.set(normalizedKey, skill.name);
        for (const label of [skill.name, ...skill.aliases]) {
            const labelKey = label.trim().toLocaleLowerCase('vi');
            if (!labelKey) {
                throw new Error(`Skill "${skill.name}" contains an empty alias.`);
            }
            const previousLabel = searchableLabels.get(labelKey);
            if (previousLabel) {
                throw new Error(`Duplicate skill label "${label}" appears in "${previousLabel}" and "${skill.name}".`);
            }
            searchableLabels.set(labelKey, skill.name);
        }
    }
}
